from typing import List

class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        if k == n:
            return [0] * n

        children = [{}]
        count = [0]
        depth = [0]
        parent = [-1]

        for w in words:
            node = 0
            for ch in w:
                nxt = children[node].get(ch)
                if nxt is None:
                    nxt = len(children)
                    children[node][ch] = nxt
                    children.append({})
                    count.append(0)
                    depth.append(depth[node] + 1)
                    parent.append(node)
                node = nxt
                count[node] += 1

        count[0] = n
        m = len(children)

        max_valid = [-1] * m
        for v in range(m):
            if count[v] >= k:
                max_valid[v] = depth[v]

        for v in range(m - 1, 0, -1):
            p = parent[v]
            if max_valid[v] > max_valid[p]:
                max_valid[p] = max_valid[v]

        ans = [0] * n
        cache = {}
        k_plus = k + 1

        for i, w in enumerate(words):
            if w in cache:
                ans[i] = cache[w]
                continue

            node = 0
            off_path = -1
            on_path = 0

            for ch in w:
                for c, child in children[node].items():
                    if c != ch:
                        mv = max_valid[child]
                        if mv > off_path:
                            off_path = mv

                node = children[node][ch]
                if count[node] >= k_plus:
                    on_path = depth[node]

            for child in children[node].values():
                mv = max_valid[child]
                if mv > off_path:
                    off_path = mv

            res = off_path if off_path > on_path else on_path
            if res < 0:
                res = 0

            ans[i] = res
            cache[w] = res

        return ans
