    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1
        pat = [ord(c) - 97 for c in str2]

        # KMP prefix function
        pi = [0] * m
        for i in range(1, m):
            j = pi[i - 1]
            while j > 0 and pat[i] != pat[j]:
                j = pi[j - 1]
            if pat[i] == pat[j]:
                j += 1
            pi[i] = j

        # KMP transitions
        trans = [[0] * 26 for _ in range(m + 1)]
        for s in range(m):
            for c in range(26):
                if c == pat[s]:
                    trans[s][c] = s + 1
                elif s == 0:
                    trans[s][c] = 0
                else:
                    trans[s][c] = trans[pi[s - 1]][c]
        trans[m] = trans[pi[m - 1]][:]

        # nextMask[s] = set of states reachable from s in one character
        nextMask = [0] * (m + 1)
        for s in range(m + 1):
            mask = 0
            for c in range(26):
                mask |= 1 << trans[s][c]
            nextMask[s] = mask

        allmask = (1 << (m + 1)) - 1
        poss = [0] * (L + 1)
        poss[L] = allmask

        # DP backwards
        for t in range(L - 1, -1, -1):
            allowed = poss[t + 1]
            if t >= m - 1:
                i = t - (m - 1)
                if str1[i] == 'T':
                    allowed &= (1 << m)
                else:
                    allowed &= ~(1 << m)

            mask = 0
            for s in range(m + 1):
                if nextMask[s] & allowed:
                    mask |= 1 << s
            poss[t] = mask

        if (poss[0] & 1) == 0:
            return ""

        # Construct lexicographically smallest answer
        res = []
        s = 0
        for t in range(L):
            allowed = poss[t + 1]
            if t >= m - 1:
                i = t - (m - 1)
                if str1[i] == 'T':
                    allowed &= (1 << m)
                else:
                    allowed &= ~(1 << m)

            for c in range(26):
                ns = trans[s][c]
                if (allowed >> ns) & 1:
                    res.append(chr(97 + c))
                    s = ns
                    break

        return ''.join(res)
