class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        n = len(points)

        # Map each point to its position along the perimeter of the square.
        pts = []
        for x, y in points:
            if y == 0:
                t = x
            elif x == side:
                t = side + y
            elif y == side:
                t = 2 * side + (side - x)
            else:
                t = 3 * side + (side - y)
            pts.append((t, x, y))

        pts.sort()
        xs = [p[1] for p in pts] * 2
        ys = [p[2] for p in pts] * 2
        m = 2 * n

        def check(D: int) -> bool:
            if D == 0:
                return True

            # nxt[i] = first index j > i such that Manhattan distance between i and j >= D
            nxt = [m] * m
            j = 0
            for i in range(m):
                if j < i + 1:
                    j = i + 1
                xi, yi = xs[i], ys[i]
                while j < m:
                    if abs(xi - xs[j]) + abs(yi - ys[j]) >= D:
                        break
                    j += 1
                nxt[i] = j

            # Try every point as the first selected point.
            for start in range(n):
                cur = start
                ok = True
                for _ in range(k - 1):
                    cur = nxt[cur]
                    if cur >= start + n:
                        ok = False
                        break
                if ok and abs(xs[cur] - xs[start]) + abs(ys[cur] - ys[start]) >= D:
                    return True
            return False

        lo, hi = 0, 2 * side
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if check(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo
