    for i in range(maxM, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % P

    def C(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * inv_fact[k] % P * inv_fact[n - k] % P

    cross = [[None] * (n + 1) for _ in range(n + 1)]
    for x in range(1, n + 1):
