                    for e in range(1, x + 1):
                        new[i + e] = (new[i + e] + a * q[e]) % P
            poly = new
            cross[x][y] = poly[:]

    internal = [[0] * (maxM + 1) for _ in range(n + 1)]
    for y in range(1, n + 1):
        max_t = y * (y - 1) // 2
