from typing import List

class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def can(x: int) -> bool:
            if x == 0:
                return True

            moves = 1
            carry = 0

            for i in range(n - 1):
                need = (x + points[i] - 1) // points[i]
                count = 1 + carry

                if count < need:
                    k = need - count
                else:
                    k = 0

                if i < n - 2:
                    moves += 2 * k + 1
                    carry = k
                else:
                    moves += 2 * k
                    need_last = (x + points[n - 1] - 1) // points[n - 1]
                    if need_last > k:
                        r = need_last - k
                        moves += 2 * r - 1

                if moves > m:
                    return False

            return True

        lo, hi = 0, max(points) * m + 1
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if can(mid):
                lo = mid
            else:
                hi = mid - 1

        return lo
